mapper.select:
SELECT br.*, e.name AS equip_name, e.serial_number AS serial_number, ut.name AS user_name, a.name AS reviewer_name FROM borrow_record br LEFT JOIN equipment e ON br.equip_id = e.id LEFT JOIN usertable ut ON br.user_id = ut.id LEFT JOIN admin a ON br.reviewer_id = a.id
AND br.equip_id = #{equipId}
AND br.user_id = #{userId}
AND br.status = #{status}
AND br.type = #{type}
AND br.reviewer_id = #{reviewerId}
AND e.name LIKE CONCAT('%', #{equipName}, '%')
AND br.original_id = #{originalId}
AND DATE(br.apply_time) >= #{startTime}
AND DATE(br.apply_time) <= #{endTime}
ORDER BY CASE br.status WHEN 'pending' THEN 1 WHEN 'approved' THEN 2 WHEN 'completed' THEN 3 WHEN 'rejected' THEN 4 ELSE 5 END ASC, apply_time DESC

